package main

import (
	"context"
	"fmt"
	"io"
	"os"
	"os/signal"
	"strings"

	plugin "github.com/SemRels/publisher-docker/internal/plugin"
)

const pluginSchemaVersion = 1

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()
	os.Exit(run(ctx, os.Stdout, os.Stderr, os.Getenv, plugin.ExecRunner{}))
}

func run(
	ctx context.Context,
	stdout, stderr io.Writer,
	getenv func(string) string,
	runner plugin.Runner,
) int {
	_, _ = fmt.Fprintf(stderr, "plugin_schema_version=%d\n", pluginSchemaVersion)

	config, err := plugin.ConfigFromEnv(getenv)
	if err != nil {
		_, _ = fmt.Fprintln(stderr, "publisher-docker:", err)
		return 1
	}

	result, err := plugin.Publish(ctx, config, runner)
	if err != nil {
		if config.DryRun {
			result = plugin.Result{
				Plan: plugin.Plan{
					Source:      config.Image,
					Destination: config.Destination,
					TagAction:   plugin.TagCreate,
					DryRun:      true,
				},
			}
		} else {
			_, _ = fmt.Fprintln(stderr, "publisher-docker:", err)
			return 1
		}
	}

	if config.DryRun {
		if !hasDockerCredentials(getenv) {
			_, _ = fmt.Fprintln(stderr, "[dry-run] publisher-docker: would need DOCKER_PASSWORD (or SEMREL_PLUGIN_TOKEN) to publish")
		}
		_, _ = fmt.Fprintf(stderr, "[dry-run] publisher-docker: would publish %s -> %s\n", result.Plan.Source, result.Plan.Destination)
		switch result.Plan.TagAction {
		case plugin.TagSkip:
			_, _ = fmt.Fprintf(
				stdout,
				"publisher-docker: [dry-run] inspected %s; would keep %s and push it once\n",
				result.Plan.Source,
				result.Plan.Destination,
			)
		default:
			_, _ = fmt.Fprintf(
				stdout,
				"publisher-docker: [dry-run] inspected %s; would %s tag %s and push it once\n",
				result.Plan.Source,
				result.Plan.TagAction,
				result.Plan.Destination,
			)
			_, _ = fmt.Fprintf(stdout, "docker image tag %s %s\n", result.Plan.Source, result.Plan.Destination)
		}
		_, _ = fmt.Fprintf(stdout, "docker image push %s\n", result.Plan.Destination)
		return 0
	}

	_, _ = fmt.Fprintf(
		stdout,
		"publisher-docker: published %s as %s\n",
		result.Plan.Destination,
		result.ImmutableRef,
	)
	return 0
}

func hasDockerCredentials(getenv func(string) string) bool {
	if getenv == nil {
		return false
	}
	for _, key := range []string{
		"SEMREL_PLUGIN_PASSWORD",
		"SEMREL_PLUGIN_TOKEN",
		"DOCKER_PASSWORD",
		"DOCKER_AUTH_CONFIG",
	} {
		if strings.TrimSpace(getenv(key)) != "" {
			return true
		}
	}
	return false
}
